from gate_manager import resolve_feature_gates

def test_case_1():
    defaults = {"roles": ["viewer", "editor"]}
    custom = {"roles": ["billing_admin"]}
    res = resolve_feature_gates("tenant_ent_1", defaults, custom)
    # The bug was that custom roles would overwrite base roles entirely
    # Instead, we should merge role lists to preserve base permissions
    expected_roles = ["viewer", "editor", "billing_admin"]
    assert res["gates"]["roles"] == expected_roles
